 v=s.cpu.registers[2]&0xffffu;v=((v>>8)|(v<<8))&0xffffu;put(&s,2,2,v);nz(&s,v,16);s.cpu.sr=(uint16_t)((s.cpu.sr&~1u)|((v>>15)&1u));s.cpu.pc=0x394cu;break;
